    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[][] edges = new int[Math.max(0, n - 1)][2];
        for (int i = 0; i < n - 1; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        List<Integer> roots = findMinHeightRoots(n, edges);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < roots.size(); i++) sb.append(roots.get(i)).append(i + 1 < roots.size() ? " " : "");
        System.out.println(sb);
    }
}
